using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class JumpSeven {
 public static string Main(){EditorApplication.delayCall+=Run;return "Scheduled motorcycle/ATV pool-house flights at 32 and 42 m/s";}
 static void Run(){var mode=Physics.simulationMode;try{EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");AudioListener.volume=0;Physics.simulationMode=SimulationMode.Script;var race=Object.FindAnyObjectByType<RaceDirector>();var car=race.vehicle;var f=BindingFlags.NonPublic|BindingFlags.Instance;typeof(VehicleSurfaceContacts).GetMethod("Reset",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);typeof(ArcadeVehicle).GetMethod("Awake",f).Invoke(car,null);car.enabled=false;var config=car.GetComponent<VehicleConfiguration>()??car.gameObject.AddComponent<VehicleConfiguration>();foreach(var body in Object.FindObjectsByType<Rigidbody>())if(body!=car.Body)body.gameObject.SetActive(false);var c=race.GetComponent<BackyardForwardCourse>();var lip=c.flightStarts[2];var axis=c.flightDirections[2];var results=new List<string>();var log=new List<string>{"case,time,x,y,z,speed,vertical,wheels,up"};
 foreach(string profile in new[]{"moto","atv"})foreach(float speed in new[]{32f,42f}){config.Apply(profile);var p=lip-axis*30;p.y=Racer.Editor.BackyardReverseAuthoring.Ground(p)+.55f;car.Body.isKinematic=false;car.Body.position=p;car.Body.rotation=Quaternion.LookRotation(axis);car.transform.SetPositionAndRotation(p,car.Body.rotation);car.Body.linearVelocity=car.Body.angularVelocity=Vector3.zero;car.ClearSteering();Physics.SyncTransforms();for(int i=0;i<45;i++){car.Simulate(0,0,0,.02f);Physics.Simulate(.02f);}car.Body.linearVelocity=(axis+Vector3.up*.16f).normalized*speed;float air=0,maxAir=0,minUp=1;bool tookOff=false,landed=false;Vector3 land=default;float takeSpeed=0;for(int i=0;i<450;i++){float along=Vector3.Dot(car.Body.position-lip,axis);if(along>0&&car.GroundedWheels==0){if(!tookOff)takeSpeed=car.ForwardSpeed;tookOff=true;air+=.02f;maxAir=Mathf.Max(maxAir,air);}else if(tookOff&&air>.5f&&car.GroundedWheels>=2){landed=true;land=car.Body.position;break;}minUp=Math.Min(minUp,car.transform.up.y);var target=lip+axis*(along+12);var delta=Quaternion.Inverse(Quaternion.LookRotation(Vector3.ProjectOnPlane(car.transform.forward,Vector3.up)))*(target-car.Body.position);float angle=Mathf.Atan2(delta.x,delta.z);float steer=Mathf.Clamp(Mathf.Atan(2*car.wheelbase*Mathf.Sin(angle)/12)/(Mathf.Lerp(car.slowSteerAngle,car.fastSteerAngle,Mathf.Clamp01(car.ForwardSpeed/car.topSpeed))*Mathf.Deg2Rad),-1,1);car.Simulate(car.ForwardSpeed<speed?1:0,car.ForwardSpeed>speed+1?.3f:0,steer,.02f);Physics.Simulate(.02f);Physics.SyncTransforms();if(i%5==0){p=car.Body.position;log.Add($"{profile}-{speed},{i*.02f:F2},{p.x:F3},{p.y:F3},{p.z:F3},{car.ForwardSpeed:F2},{car.Body.linearVelocity.y:F2},{car.GroundedWheels},{car.transform.up.y:F3}");}}
 results.Add((landed&&land.x>410&&land.x<474&&minUp>.7f&&maxAir>.6f?"PASS ":"FAIL ")+$"{profile} entry={speed} takeoff={takeSpeed:F2} air={maxAir:F2} landed={landed} landing={land:F3} minUp={minUp:F3}");File.WriteAllLines("Docs/SevenCorrections/jump-driving.txt",results);}
 File.WriteAllLines("Docs/SevenCorrections/jump-driving.csv",log);File.WriteAllText("Docs/SevenCorrections/jump-done.txt","Complete");}catch(Exception e){File.WriteAllText("Docs/SevenCorrections/jump-error.txt",e.ToString());}finally{Physics.simulationMode=mode;EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");}}
}
